where.if:
AND a.animation_id IN (
SELECT at.animation_id
FROM animation_tags at
WHERE at.tag_id IN

  #{tagId}

GROUP BY at.animation_id
HAVING COUNT(DISTINCT at.tag_id) = #{condition.getTagIdsSize}
)

mapper.select:
SELECT a.animation_id, a.title, a.image_path, c.name AS company_name, a.summary, a.season, IF(b.user_id IS NOT NULL, 1, 0) as is_bookmarked, a.bookmark_count, a.review_count, ROUND( CASE WHEN a.review_count > 0 THEN a.rating_sum / a.review_count ELSE 0 END, 1 ) AS average_rating, t.text as tag_names FROM animations a LEFT JOIN bookmarks b ON a.animation_id = b.animation_id AND b.user_id = #{userId} LEFT JOIN companies c ON a.company_id = c.company_id LEFT JOIN animation_tags at ON a.animation_id = at.animation_id LEFT JOIN tags t ON at.tag_id = t.tag_id
WHERE a.animation_id IN
#{id}
ORDER BY FIELD(a.animation_id,
#{id}
)
